func (q *Queries) ListKnowledgeTargetRows(ctx context.Context, arg ListKnowledgeTargetRowsParams) ([]CollaborationKnowledgeCandidate, error) {
	rows, err := q.db.Query(ctx, listKnowledgeTargetRows,
		arg.TargetKind,
		arg.WorkspaceID,
		arg.ProjectID,
		arg.TargetConfirmer,
		arg.ViewerID,
		arg.AfterAt,
		arg.AfterID,
		arg.ThroughAt,
		arg.ThroughID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CollaborationKnowledgeCandidate{}
	for rows.Next() {
		var i CollaborationKnowledgeCandidate
		if err := rows.Scan(
			&i.ID,
			&i.LineageID,
			&i.Version,
			&i.SourceWorkspaceID,
			&i.SourceIssueID,
			&i.TargetKind,
			&i.TargetWorkspaceID,
			&i.TargetProjectID,
			&i.Content,
			&i.Summary,
			&i.ContentSha256,
			&i.Sources,
			&i.Evidence,
			&i.Applicability,
			&i.ProposedByUserID,
			&i.ProposedAt,
			&i.ExpiresAt,
			&i.SupersedesCandidateID,
			&i.DerivedFromCandidateID,
			&i.State,
			&i.StateRevision,
			&i.ApprovedByUserID,
			&i.ApprovedAt,
			&i.LastDecidedByUserID,
			&i.LastDecidedAt,
			&i.LastDecisionReason,
			&i.PublishedTargetRevision,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

